-- 4. Inserción de auditoría en historial_consultas
INSERT INTO isft189.historial_consultas
    (id, usuario_id, pregunta, respuesta, fecha_consulta) VALUES
    (1, 4, '¿Cuál es la correlatividad de Base de Datos en Análisis y Desarrollo de Aplicaciones?',
        'Según la Resolución 6175/03, para cursar y aprobar Base de Datos se requiere tener aprobada Programación I.',
        '2026-08-10 10:15:00-03'),
    (2, 4, '¿Cuántas horas dura la carrera Análisis, Desarrollo y Programación de Aplicaciones?',
        'Tiene una duración de 3 años y una carga horaria total de 1824 horas reloj.',
        '2026-08-12 11:05:00-03'),
    (3, 5, '¿Qué porcentaje de asistencia necesito para mantener la regularidad?',
        'El reglamento general del estudiante establece una asistencia mínima obligatoria del 75%.',
        '2026-08-13 09:40:00-03'),
    (4, 5, '¿En qué meses se sustancian los exámenes finales?',
        'Según el reglamento general, los turnos ordinarios se realizan en julio/agosto y noviembre/diciembre.',
        '2026-08-15 16:20:00-03'),
    (5, 6, '¿Qué necesito para cursar Desarrollo de sistemas Web en Desarrollo de Software?',
        'Se requiere Introducción a la programación, Administración y gestión de base de datos y Diseño Web.',
        '2026-08-18 12:30:00-03'),
    (6, 3, '¿Cuál es el plazo para justificar una inasistencia médica?',
        'El plazo máximo de presentación del certificado médico es de 48 horas hábiles posteriores según la Resolución 123/2024.',
        '2026-08-20 14:10:00-03');

SELECT setval(pg_get_serial_sequence('isft189.historial_consultas', 'id'),
              (SELECT MAX(id) FROM isft189.historial_consultas));

COMMIT;

-- Consultas de validación e integración RAG (Consigna Sección D)

-- Consulta 1: Búsqueda por similitud vectorial pura (Top-3 más cercanos al fragmento semilla id = 7)
SELECT v.id,
       v.documento_id,
       d.titulo AS titulo_documento,
       LEFT(v.contenido, 80) || '...' AS extracto,
       ROUND((v.embedding <=> (SELECT embedding FROM isft189.documentos_vectoriales WHERE id = 7))::numeric, 4) AS distancia_coseno
FROM   isft189.documentos_vectoriales v
JOIN   isft189.documentos_metadata d ON d.id = v.documento_id
ORDER  BY v.embedding <=> (SELECT embedding FROM isft189.documentos_vectoriales WHERE id = 7)
LIMIT  3;

-- Consulta 2: Búsqueda híbrida con filtro relacional estricto (documentos activos de tipo 'reglamento')
SELECT v.id,
       d.titulo,
       d.tipo_documento,
       LEFT(v.contenido, 70) || '...' AS fragmento,
       ROUND((v.embedding <=> (SELECT embedding FROM isft189.documentos_vectoriales WHERE id = 5))::numeric, 4) AS distancia_coseno
FROM   isft189.documentos_vectoriales v
JOIN   isft189.documentos_metadata d ON d.id = v.documento_id
WHERE  d.activo = TRUE
  AND  d.tipo_documento = 'reglamento'
ORDER  BY v.embedding <=> (SELECT embedding FROM isft189.documentos_vectoriales WHERE id = 5)
LIMIT  3;

-- Consulta 3: Búsqueda híbrida con filtro sobre JSONB estructurado + documento activo
SELECT v.id,
       v.metadata->>'carrera' AS carrera_metadata,
       v.metadata->>'materia' AS materia,
       LEFT(v.contenido, 80) AS contenido,
       ROUND((v.embedding <=> (SELECT embedding FROM isft189.documentos_vectoriales WHERE id = 7))::numeric, 4) AS distancia
FROM   isft189.documentos_vectoriales v
JOIN   isft189.documentos_metadata d ON d.id = v.documento_id
WHERE  d.activo = TRUE
  AND  v.metadata @> '{"carrera": "Tecnicatura Superior en Análisis, Desarrollo y Programación de Aplicaciones"}'
ORDER  BY v.embedding <=> (SELECT embedding FROM isft189.documentos_vectoriales WHERE id = 7)
LIMIT  3;

-- Consulta 4: Auditoría cruzada - Historial de consultas con usuario y conteo de interacciones
SELECT u.nombre,
       u.rol,
       COUNT(h.id) AS total_consultas,
       MAX(h.fecha_consulta) AS ultima_consulta
FROM   isft189.usuarios u
LEFT JOIN isft189.historial_consultas h ON h.usuario_id = u.id
GROUP  BY u.id, u.nombre, u.rol
ORDER  BY total_consultas DESC, u.nombre;
